<section class="card" id="members"><h2>用户</h2><form method="get"><input type="hidden" name="section" value="users"><input name="q" value="<?= $e($q) ?>" placeholder="账号或邮箱"><button>搜索</button></form><div class="table"><table><tr><th>用户</th><th>邮箱</th><th>状态</th><th>操作</th></tr><?php foreach($members as $m): ?><tr><td><?= $e($m['display_name']) ?><small><?= $e($m['username']) ?></small></td><td><?= $e($m['email']??'—') ?></td><td><?= $m['enabled']?'正常':'禁用' ?></td><td><?php if($m['role']!=='admin'): ?><form method="post" action="/admin/user"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="id" value="<?= $e($m['id']) ?>"><input type="hidden" name="enabled" value="<?= $m['enabled']?'0':'1' ?>"><button class="secondary"><?= $m['enabled']?'禁用':'启用' ?></button></form><?php endif ?></td></tr><?php endforeach ?></table></div><p><a href="?section=users&amp;page=<?= max(1,$page-1) ?>&amp;q=<?= $e(urlencode($q)) ?>">上一页</a> · <?= $page ?> · <a href="?section=users&amp;page=<?= $page+1 ?>&amp;q=<?= $e(urlencode($q)) ?>">下一页</a></p></section>
<details class="card audit-panel"><summary>登录与管理审计记录</summary><section class="card"><h2>最近 50 条审计记录</h2><div class="table"><table><tr><th>时间（UTC）</th><th>事件</th><th>账号 ID</th><th>说明</th></tr><?php foreach($events as $event): ?><tr><td><?= $e(gmdate('Y-m-d H:i:s',(int)$event['created_at'])) ?></td><td><?= $e($event['event']) ?></td><td><?= $e($event['user_id']??'—') ?></td><td><?= $e($event['detail']) ?></td></tr><?php endforeach ?></table></div></section></details>